package com.collabboard.auth;
import com.collabboard.auth.*;import com.collabboard.dto.*;import com.collabboard.security.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import jakarta.servlet.http.*;import java.util.*;
@Service public class AuthService {private final AppUserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;private final boolean secure;public AuthService(AppUserRepository u,PasswordEncoder e,JwtService j,@Value("${app.cookie.secure:false}")boolean secure){users=u;encoder=e;jwt=j;this.secure=secure;}
 @Transactional public UserResponse signup(SignUpRequest r,HttpServletResponse response){if(r.password().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72)throw new IllegalArgumentException("Password must be no more than 72 UTF-8 bytes");if(!r.password().equals(r.confirmPassword()))throw new IllegalArgumentException("Passwords do not match");String email=r.email().trim().toLowerCase(Locale.ROOT);if(users.existsByEmailIgnoreCase(email))throw new EmailInUseException();AppUser u=users.save(new AppUser(UUID.randomUUID().toString(),r.name().trim(),email,encoder.encode(r.password())));setCookie(response,new AuthPrincipal(u.getId(),u.getName(),u.getEmail(),u.getTokenVersion()));return dto(u);}
 public UserResponse login(LoginRequest r,HttpServletResponse response){AppUser u=users.findByEmailIgnoreCase(r.email().trim()).orElseThrow(BadCredentialsException::new);if(!encoder.matches(r.password(),u.getPasswordHash()))throw new BadCredentialsException();setCookie(response,new AuthPrincipal(u.getId(),u.getName(),u.getEmail(),u.getTokenVersion()));return dto(u);}
 public void logout(HttpServletResponse response){Cookie c=new Cookie("COLLABBOARD_SESSION","");c.setPath("/");c.setHttpOnly(true);c.setSecure(secure);c.setAttribute("SameSite","Strict");c.setMaxAge(0);response.addCookie(c);}
 private void setCookie(HttpServletResponse res,AuthPrincipal p){Cookie c=new Cookie("COLLABBOARD_SESSION",jwt.issue(p));c.setPath("/");c.setHttpOnly(true);c.setSecure(secure);c.setAttribute("SameSite","Strict");c.setMaxAge((int)(jwt.ttl()/1000));res.addCookie(c);}
 public UserResponse dto(AppUser u){return new UserResponse(u.getId(),u.getName(),u.getEmail());}
 public static class BadCredentialsException extends RuntimeException{}public static class EmailInUseException extends RuntimeException{}
}


